async () => {
  const W = window; const sleep = ms => new Promise(r=>setTimeout(r,ms));
  const mg = () => W.MinigameFramework.currentMinigame; const C = () => mg() && mg().container;
  const q = s => C() && C().querySelector(s); const qa = s => C() ? [...C().querySelectorAll(s)] : [];
  const ts = () => mg().getTestState().triage;
  const diag = { startStep: ts().step, total: ts().total, rowSel: null, verdictSel: null, loops: 0, step: null };
  const start = q('.tri-start'); if (start) { start.click(); await sleep(150); }
  const rowSelectors = ['.mail-row', '.tri-card', '.tri-item', '.tri-row', '.tri-message'];
  for (let i = 0; i < (diag.total || 8) * 4 + 8; i++) {
    diag.loops = i;
    const st = ts(); diag.step = st.step;
    if (st.step === 'result') break;
    // open a row if a verdict isn't already offered
    let verdicts = qa('.tri-verdict').filter(b => !b.disabled && b.offsetParent !== null);
    if (!verdicts.length) {
      for (const rs of rowSelectors) {
        const rows = qa(rs);
        if (rows.length) { diag.rowSel = rs; const r = rows.find(x => x.offsetParent !== null) || rows[0]; r.click(); await sleep(120); break; }
      }
      verdicts = qa('.tri-verdict').filter(b => !b.disabled && b.offsetParent !== null);
    }
    if (verdicts.length) { diag.verdictSel = verdicts[0].getAttribute('data-action') || verdicts[0].getAttribute('data-verdict') || 'first'; verdicts[0].click(); await sleep(100); }
    else { diag.verdictSel = 'NONE'; }
    const confirm = q('.tri-confirm'); if (confirm && !confirm.disabled) { confirm.click(); await sleep(140); }
    const next = q('.tri-feedback-next') || q('.tri-fb-next') || q('.tri-next'); if (next && !next.disabled) { next.click(); await sleep(140); }
  }
  diag.step = ts().step;
  W.__triageDiag = diag;
  return diag.step === 'result';
}

async () => {
  const W = window; const sleep = ms => new Promise(r=>setTimeout(r,ms));
  const mg = () => W.MinigameFramework.currentMinigame; const C = () => mg() && mg().container;
  const q = s => C() && C().querySelector(s);
  const end = Date.now() + 10000;
  while (Date.now() < end) { const f = q('.tri-finish'); if (f && !f.disabled) { f.click(); return true; } await sleep(150); }
  return false;
}
